class RewardModel(nn.Module):
    def __init__(self, backbone):
        super().__init__()
        self.backbone = backbone  # pretrained transformer, last hidden state available
        self.value_head = nn.Linear(backbone.config.hidden_size, 1)

    def forward(self, input_ids, attention_mask):
        hidden = self.backbone(input_ids, attention_mask=attention_mask).last_hidden_state
        last_token_idx = attention_mask.sum(dim=1) - 1
        pooled = hidden[torch.arange(hidden.size(0)), last_token_idx]
        return self.value_head(pooled).squeeze(-1)  # scalar reward per sequence

def extract_final_answer(text: str) -> str | None:
    import re
    match = re.search(r"(?:answer is|=)\s*(-?\d+\.?\d*)\s*$", text.strip())
    return match.group(1) if match else None

def verifiable_reward(generated_text: str, ground_truth: str) -> float:
    pred = extract_final_answer(generated_text)
    if pred is None:
        return -1.0  # unparseable output penalized, not silently zero
    return 1.0 if abs(float(pred) - float(ground_truth)) < 1e-6 else 0.0

class SparseAutoencoder(nn.Module):
    def __init__(self, d_model, d_hidden, l1_coef=1e-3):
        super().__init__()
        self.encoder = nn.Linear(d_model, d_hidden)
        self.decoder = nn.Linear(d_hidden, d_model, bias=False)
        self.l1_coef = l1_coef

    def forward(self, x):
        codes = F.relu(self.encoder(x))
        recon = self.decoder(codes)
        return recon, codes

