def per_token_kl(policy_logp, ref_logp, generated_ids):
    policy_tok_logp = policy_logp.gather(-1, generated_ids.unsqueeze(-1)).squeeze(-1)
    ref_tok_logp = ref_logp.gather(-1, generated_ids.unsqueeze(-1)).squeeze(-1)
    return policy_tok_logp - ref_tok_logp  # per-token KL estimate (policy log-prob minus ref log-prob)

class QueryPlanEnv(gym.Env):
    def __init__(self, queries, db_connection):
        super().__init__()
        self.queries = queries
        self.db = db_connection
        self.action_space = gym.spaces.Discrete(N_CANDIDATE_PLANS)
        self.observation_space = gym.spaces.Box(low=-1e6, high=1e6, shape=(FEATURE_DIM,))

    def reset(self, *, seed=None, options=None):
        self.current_query = random.choice(self.queries)
        self.optimizer_cost = get_optimizer_estimated_cost(self.db, self.current_query)
        return encode_query_features(self.current_query), {}

    def step(self, action):
        plan = self.candidate_plans(self.current_query)[action]
        actual_cost = execute_with_plan_hint(self.db, self.current_query, plan, timeout=10)
        reward = (self.optimizer_cost - actual_cost) / max(self.optimizer_cost, 1e-6)
        return encode_query_features(self.current_query), reward, True, False, {"actual_cost": actual_cost}

