def sequence_logp(logits, labels, mask):
    logp = F.log_softmax(logits, dim=-1)
    token_logp = logp.gather(-1, labels.unsqueeze(-1)).squeeze(-1)
    return (token_logp * mask).sum(dim=-1)  # NOT .mean()

