def logit_lens(model, input_ids, layer_idx):
    captured = {}
    def hook(module, inp, out):
        captured["resid"] = out
    handle = model.transformer.h[layer_idx].register_forward_hook(hook)
    model(input_ids)
    handle.remove()
    normed = model.transformer.ln_f(captured["resid"])  # apply final layer norm
    early_logits = normed @ model.transformer.wte.weight.T  # unembed
    return early_logits

