        super().__init__()
        self.block = block

    def forward(self, x):
        return checkpoint(self.block, x, use_reentrant=False)

def pack_sequences(documents, seq_len, eos_id):
    packed, current, current_ids = [], [], []
    for doc in documents:
        current += doc + [eos_id]
        while len(current) >= seq_len:
            packed.append(current[:seq_len])
            current = current[seq_len:]
    if current:
        packed.append(current + [eos_id] * (seq_len - len(current)))
    return packed

class LoRALinear(nn.Module):
    def __init__(self, base_layer: nn.Linear, rank=8, alpha=16):
        super().__init__()
        self.base = base_layer
        for p in self.base.parameters():
            p.requires_grad = False
        in_f, out_f = base_layer.in_features, base_layer.out_features
        self.A = nn.Parameter(torch.randn(rank, in_f) * 0.01)
        self.B = nn.Parameter(torch.zeros(out_f, rank))
        self.scale = alpha / rank

    def forward(self, x):
        return self.base(x) + (x @ self.A.T @ self.B.T) * self.scale

