def extract_activations(model, texts, layer_idx, tokenizer):
    acts = []
    for text in texts:
        ids = tokenizer(text, return_tensors="pt").input_ids
        hidden = model(ids, output_hidden_states=True).hidden_states[layer_idx]
        acts.append(hidden[0, -1].numpy())  # last-token representation
    return np.stack(acts)

